import sympy as sp
A=sp.symbols('A')
x=2*A
e=(2+sp.tan(x)**2+sp.cot(x)**2)/(sp.sec(x)*sp.csc(x))
opts={'A':sp.sec(x)*sp.csc(x),'B':sp.cot(x)-sp.csc(x),'C':sp.sec(x)+sp.csc(x),'D':sp.sec(x)+sp.tan(x)}
def eq(a,b):
    return all(abs(float((a-b).subs(A,t)))<1e-9 for t in (0.3,0.5,0.7))
assert eq(e,opts['A'])
for k in 'BCD': assert not eq(e,opts[k])
